CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 TEXT UNIQUE, c1 REAL CHECK(c1 IS NULL OR length(c1) < 40), c2 TEXT COLLATE NOCASE, c3 REAL COLLATE NOCASE);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INT COLLATE NOCASE, c1 VARCHAR(10) CHECK(c1 IS NULL OR length(c1) < 40), c2 NUMERIC, c3 REAL NOT NULL DEFAULT 0, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(-25, NULL, 710.39, 622.49, NULL);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES('chi', 'café', 'zeta', 0, 6);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(-1, -509, '0x1F', 0, 1);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(x'', 0, NULL, 'rho', 8);
SELECT length('pi'), upper('pi'), lower('pi'), substr('pi', 4, 5), instr('pi', 'tau'), replace('pi', 'a', 'XY'), trim('pi'), ltrim('pi', 'ab'), hex('pi'), quote('pi'), unicode('pi'), 'pi' LIKE '%a_', 'pi' GLOB 'a*', char(89, 434), 'pi' || 'tau', 'pi' < 'tau', 'pi' = 'tau' COLLATE NOCASE;
SELECT length(' pad '), upper(' pad '), lower(' pad '), substr(' pad ', -2, 2), instr(' pad ', 'xi'), replace(' pad ', 'é', '_'), trim(' pad '), ltrim(' pad ', 'ab'), hex(' pad '), quote(' pad '), unicode(' pad '), ' pad ' LIKE '_', ' pad ' GLOB '?', char(83, 790), ' pad ' || 'xi', ' pad ' < 'xi', ' pad ' = 'xi' COLLATE NOCASE;
SELECT length('phi'), upper('phi'), lower('phi'), substr('phi', 4, 0), instr('phi', 'delta'), replace('phi', 'a', '_'), trim('phi'), ltrim('phi', 'ab'), hex('phi'), quote('phi'), unicode('phi'), 'phi' LIKE '%a_', 'phi' GLOB 'a*', char(80, 381), 'phi' || 'delta', 'phi' < 'delta', 'phi' = 'delta' COLLATE NOCASE;
SELECT length('kappa'), upper('kappa'), lower('kappa'), substr('kappa', -1, 1), instr('kappa', 'café'), replace('kappa', 'a', ''), trim('kappa'), ltrim('kappa', 'ab'), hex('kappa'), quote('kappa'), unicode('kappa'), 'kappa' LIKE 'A%', 'kappa' GLOB '*[a-m]*', char(82, 560), 'kappa' || 'café', 'kappa' < 'café', 'kappa' = 'café' COLLATE NOCASE;
SELECT length('alpha'), upper('alpha'), lower('alpha'), substr('alpha', -1, 4), instr('alpha', 'NULL'), replace('alpha', 'e', 'XY'), trim('alpha'), ltrim('alpha', 'ab'), hex('alpha'), quote('alpha'), unicode('alpha'), 'alpha' LIKE '%é%', 'alpha' GLOB '*[a-m]*', char(81, 378), 'alpha' || 'NULL', 'alpha' < 'NULL', 'alpha' = 'NULL' COLLATE NOCASE;
SELECT length('señor'), upper('señor'), lower('señor'), substr('señor', 3, 3), instr('señor', 'chi'), replace('señor', 'e', 'XY'), trim('señor'), ltrim('señor', 'ab'), hex('señor'), quote('señor'), unicode('señor'), 'señor' LIKE '_', 'señor' GLOB '*[a-m]*', char(72, 475), 'señor' || 'chi', 'señor' < 'chi', 'señor' = 'chi' COLLATE NOCASE;
SELECT a.id, b.id, a.c3, b.c2 FROM t1 a CROSS JOIN t1 b ORDER BY 1, 2 LIMIT 19;
SELECT count(*) FROM t1 a JOIN t1 b USING(id) WHERE a.c3 IS NULL;
